function AlertsDiscovery() {
  const [query, setQuery] = useState("");
  const [type, setType] = useState("All");
  const [severity, setSeverity] = useState("All");
  const [product, setProduct] = useState("All");
  const [selected, setSelected] = useState<typeof alertRows[number] | null>(null);
  const filtered = alertRows.filter(alert => [alert.title, alert.description, alert.product, alert.standard].join(" ").toLowerCase().includes(query.toLowerCase()) && (type === "All" || alert.type === type) && (severity === "All" || alert.severity === severity) && (product === "All" || alert.product === product));
  const reset = () => { setQuery(""); setType("All"); setSeverity("All"); setProduct("All"); };
  const tone = (value: string) => value === "Critical" ? "rose" : value === "Action Required" ? "amber" : "blue";
  return <Shell page="alerts"><PageHeading eyebrow="Compliance monitoring" title="Compliance Alerts" description="Stay informed about changes, missing requirements and product-specific compliance updates."/><section className="mt-6 rounded-2xl border border-blue-200 bg-blue-50 p-5 sm:p-6"><div className="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between"><div><div className="flex items-center gap-2"><Icon name="sparkle" className="h-5 w-5 text-blue-700"/><h2 className="font-bold text-blue-900">What changed for me?</h2></div><p className="mt-2 max-w-2xl text-sm leading-6 text-blue-800">For your Electric Kettle passport, recent mock updates affect testing evidence, product marking review and certification preparation.</p><div className="mt-4 grid grid-cols-3 gap-4"><div><p className="text-xl font-bold text-blue-900">2</p><p className="text-xs text-blue-700">requirements changed</p></div><div><p className="text-xl font-bold text-blue-900">1</p><p className="text-xs text-blue-700">new applicable requirement</p></div><div><p className="text-xl font-bold text-blue-900">1</p><p className="text-xs text-blue-700">pending action</p></div></div></div><button onClick={() => setSelected(alertRows[1])} className="shrink-0 rounded-xl bg-blue-700 px-4 py-2.5 text-sm font-semibold text-white hover:bg-blue-800">Review Changes</button></div></section><div className="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Missing Requirements" value="1" trend="Action" icon="alert" tone="bg-rose-50 text-rose-600"/><Stat label="Standard Changes" value="2" trend="+1" icon="book" tone="bg-amber-50 text-amber-600"/><Stat label="New Requirements" value="1" trend="New" icon="plus" tone="bg-blue-50 text-blue-600"/><Stat label="Product-Specific Alerts" value="4" trend="+2" icon="passport" tone="bg-violet-50 text-violet-600"/></div><section className="mt-7 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6"><div className="grid gap-3 lg:grid-cols-[1.5fr_repeat(3,1fr)_auto]"><div className="relative"><Icon name="search" className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"/><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search compliance alerts..." aria-label="Search compliance alerts" className="w-full rounded-xl border border-slate-200 bg-slate-50 py-3 pl-9 pr-3 text-sm outline-none focus:border-blue-400 focus:bg-white"/></div><select value={type} onChange={e => setType(e.target.value)} aria-label="Alert Type" className="rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm text-slate-600 outline-none"><option value="All">Alert Type: All</option><option>Missing Requirement</option><option>Standard Change</option><option>New Requirement</option><option>Product Alert</option></select><select value={severity} onChange={e => setSeverity(e.target.value)} aria-label="Severity" className="rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm text-slate-600 outline-none"><option value="All">Severity: All</option><option>Critical</option><option>Action Required</option><option>Informational</option></select><select value={product} onChange={e => setProduct(e.target.value)} aria-label="Product" className="rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm text-slate-600 outline-none"><option value="All">Product: All</option><option>Electric Kettle</option></select><button onClick={reset} className="rounded-xl border border-slate-200 px-4 py-3 text-sm font-semibold text-slate-600 hover:bg-slate-50">Reset</button></div></section><section className="mt-7"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-bold text-slate-900">Active alerts</h2><p className="mt-1 text-sm text-slate-500">Frontend demo records for your compliance workspace.</p></div><span className="text-xs text-slate-400">{filtered.length} alerts</span></div>{filtered.length === 0 ? <div className="rounded-2xl border border-dashed border-slate-300 bg-white p-12 text-center"><span className="mx-auto grid h-12 w-12 place-items-center rounded-full bg-emerald-50 text-emerald-600"><Icon name="check" className="h-6 w-6"/></span><h3 className="mt-4 font-bold text-slate-900">No active alerts</h3><p className="mt-1 text-sm text-slate-500">No mock alerts match these filters. Try resetting your search.</p><button onClick={reset} className="mt-4 text-sm font-semibold text-blue-700">Reset filters</button></div> : <div className="space-y-4">{filtered.map(alert => <article key={alert.title} className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6"><div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div className="flex gap-4"><span className={`mt-1 h-2.5 w-2.5 shrink-0 rounded-full ${alert.severity === "Critical" ? "bg-rose-500" : alert.severity === "Action Required" ? "bg-amber-500" : "bg-blue-500"}`}/><div><div className="flex flex-wrap items-center gap-2"><Badge tone={tone(alert.severity) as "rose" | "amber" | "blue"}>{alert.severity}</Badge><span className="text-xs text-slate-400">{alert.type}</span></div><h3 className="mt-2 font-bold text-slate-900">{alert.title}</h3><p className="mt-1 max-w-2xl text-sm leading-6 text-slate-500">{alert.description}</p><div className="mt-3 flex flex-wrap gap-x-5 gap-y-1 text-xs text-slate-400"><span>Product: <b className="text-slate-600">{alert.product}</b></span><span>Standard: <b className="text-slate-600">{alert.standard}</b></span><span>{alert.date}</span></div></div></div><div className="flex shrink-0 gap-2 lg:pt-1"><button onClick={() => setSelected(alert)} className="rounded-xl border border-slate-200 px-3 py-2 text-xs font-semibold text-slate-700 hover:bg-slate-50">View details</button><button onClick={e => { e.currentTarget.textContent = "Reviewed"; }} className="rounded-xl bg-blue-700 px-3 py-2 text-xs font-semibold text-white hover:bg-blue-800">Mark as reviewed</button></div></div></article>)}</div>}</section>{selected && <div className="fixed inset-0 z-30 flex items-end justify-center bg-slate-900/40 p-0 sm:items-center sm:p-6"><div role="dialog" aria-modal="true" aria-labelledby="alert-detail-title" className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-t-2xl bg-white p-5 shadow-xl sm:rounded-2xl sm:p-6"><div className="flex items-start justify-between gap-4"><div><Badge tone={tone(selected.severity) as "rose" | "amber" | "blue"}>{selected.severity}</Badge><h2 id="alert-detail-title" className="mt-2 text-xl font-bold text-slate-900">{selected.title}</h2></div><button onClick={() => setSelected(null)} aria-label="Close alert details" className="rounded-lg p-2 text-xl text-slate-400 hover:bg-slate-100">×</button></div><div className="mt-5 space-y-4 text-sm"><div><h3 className="font-bold text-slate-900">What changed</h3><p className="mt-1 leading-6 text-slate-500">{selected.changed}</p></div><div><h3 className="font-bold text-slate-900">Why it matters</h3><p className="mt-1 leading-6 text-slate-500">{selected.why}</p></div><div className="grid gap-4 sm:grid-cols-2"><Mini label="Affected product" value={selected.product} detail={selected.standard}/><Mini label="Related requirement" value={selected.requirement} detail="Mock requirement mapping"/></div><div><h3 className="font-bold text-slate-900">Recommended action</h3><p className="mt-1 leading-6 text-slate-500">{selected.action}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-xs font-bold text-blue-700">Reference / source placeholder</p><p className="mt-1 text-xs text-slate-500">{selected.source}</p></div></div><div className="mt-6 flex gap-2"><button onClick={() => setSelected(null)} className="rounded-xl bg-blue-700 px-4 py-2.5 text-sm font-semibold text-white">Mark as reviewed</button><button onClick={() => setSelected(null)} className="rounded-xl border border-slate-200 px-4 py-2.5 text-sm font-semibold text-slate-700">Close</button></div></div></div>}</Shell>;
}

const standardRows = [
  { code: "IS 4250", title: "Domestic electric kettles", category: "Electrical Appliances", scheme: "Product Certification", status: "Applicable", summary: "Mock mapping for domestic electric kettle product profiles.", requirements: ["Electrical safety evidence", "Product marking and rated capacity", "Factory quality-control records"], docs: "Test reports, product drawings and manufacturer details", testing: "Dielectric strength, temperature and functional safety tests" },
  { code: "IS 302-2-15", title: "Safety of household electrical appliances — Particular requirements", category: "Electrical Appliances", scheme: "Product Certification", status: "Applicable", summary: "Mock safety reference for household appliance assessments.", requirements: ["Protection against electric shock", "Heating and abnormal operation checks", "Insulation and leakage controls"], docs: "Technical file, drawings and safety test evidence", testing: "Insulation, leakage current and abnormal operation tests" },
  { code: "IS 1293", title: "Plugs and socket-outlets and couplers", category: "Electrical Accessories", scheme: "Product Certification", status: "Under Review", summary: "Mock related standard requiring product-context confirmation.", requirements: ["Dimensional compliance", "Material and construction checks", "Marking requirements"], docs: "Component specifications and supplier evidence", testing: "Mechanical endurance and temperature-rise tests" },
  { code: "IS 694", title: "PVC insulated cables", category: "Electrical Accessories", scheme: "Product Certification", status: "Not Applicable", summary: "Included as a mock record to demonstrate applicability review.", requirements: ["Conductor and insulation characteristics", "Voltage rating confirmation"], docs: "Cable specification and supplier certificate", testing: "Voltage, insulation and conductor tests" },
];
function StandardsDiscovery() {
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("All");
  const [scheme, setScheme] = useState("All");
  const [status, setStatus] = useState("All");
  const [selected, setSelected] = useState<typeof standardRows[number] | null>(null);
  const filtered = standardRows.filter(row => [row.code, row.title, row.category].join(" ").toLowerCase().includes(query.toLowerCase()) && (category === "All" || row.category === category) && (scheme === "All" || row.scheme === scheme) && (status === "All" || row.status === status));
  const reset = () => { setQuery(""); setCategory("All"); setScheme("All"); setStatus("All"); };
  return <Shell page="standards"><PageHeading eyebrow="BIS knowledge base" title="Standards & Requirements" description="Explore applicable BIS standards and product compliance requirements."/><div className="mt-6 rounded-2xl border border-blue-200 bg-blue-50 p-4 text-sm leading-6 text-blue-900"><b>Demo data notice:</b> These frontend records are illustrative mock data for this prototype. Verify final applicability, revisions and certification requirements against official BIS information.</div><section className="mt-6 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6"><div className="grid gap-3 lg:grid-cols-[1.5fr_repeat(3,1fr)_auto]"><div className="relative"><Icon name="search" className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"/><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search by standard code, title or product category..." aria-label="Search standards" className="w-full rounded-xl border border-slate-200 bg-slate-50 py-3 pl-9 pr-3 text-sm outline-none focus:border-blue-400 focus:bg-white"/></div><select value={category} onChange={e => setCategory(e.target.value)} aria-label="Product Category" className="rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm text-slate-600 outline-none"><option value="All">Product Category: All</option><option>Electrical Appliances</option><option>Electrical Accessories</option></select><select value={scheme} onChange={e => setScheme(e.target.value)} aria-label="Compliance Scheme" className="rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm text-slate-600 outline-none"><option value="All">Compliance Scheme: All</option><option>Product Certification</option></select><select value={status} onChange={e => setStatus(e.target.value)} aria-label="Status" className="rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm text-slate-600 outline-none"><option value="All">Status: All</option><option>Applicable</option><option>Under Review</option><option>Not Applicable</option></select><button onClick={reset} className="rounded-xl border border-slate-200 px-4 py-3 text-sm font-semibold text-slate-600 hover:bg-slate-50">Reset</button></div></section><section className="mt-7 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 p-5 sm:px-6"><div><h2 className="font-bold text-slate-900">Standards library</h2><p className="mt-1 text-sm text-slate-500">{filtered.length} mock records match your current filters.</p></div><span className="text-xs text-slate-400">Showing demo records</span></div><div className="overflow-x-auto"><table className="w-full min-w-[1050px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-400"><tr><th className="px-6 py-3">Standard Code</th><th className="px-6 py-3">Standard Title</th><th className="px-6 py-3">Product Category</th><th className="px-6 py-3">Scheme</th><th className="px-6 py-3">Requirements</th><th className="px-6 py-3">Status</th><th className="px-6 py-3">Action</th></tr></thead><tbody className="divide-y divide-slate-100">{filtered.map(row => <tr key={row.code} className="hover:bg-slate-50/70"><td className="px-6 py-4 font-bold text-blue-700">{row.code}</td><td className="max-w-xs px-6 py-4 font-medium text-slate-700">{row.title}</td><td className="px-6 py-4 text-slate-500">{row.category}</td><td className="px-6 py-4 text-slate-500">{row.scheme}</td><td className="px-6 py-4 text-slate-500">{row.requirements.length} key areas</td><td className="px-6 py-4"><Badge tone={row.status === "Applicable" ? "green" : row.status === "Under Review" ? "amber" : "slate"}>{row.status}</Badge></td><td className="px-6 py-4"><button onClick={() => setSelected(row)} className="font-semibold text-blue-700 hover:text-blue-900">View Details</button></td></tr>)}</tbody></table></div><div className="flex items-center justify-between border-t border-slate-100 p-5 sm:px-6"><p className="text-xs text-slate-400">Showing {filtered.length} of {standardRows.length} demo standards</p><button className="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-600 hover:bg-slate-50">Load More</button></div></section>{selected && <div className="fixed inset-0 z-30 flex items-end justify-center bg-slate-900/40 p-0 sm:items-center sm:p-6"><div role="dialog" aria-modal="true" aria-labelledby="standard-detail-title" className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-t-2xl bg-white p-5 shadow-xl sm:rounded-2xl sm:p-6"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-wide text-blue-700">{selected.code}</p><h2 id="standard-detail-title" className="mt-1 text-xl font-bold text-slate-900">{selected.title}</h2></div><button onClick={() => setSelected(null)} aria-label="Close standard details" className="rounded-lg p-2 text-xl text-slate-400 hover:bg-slate-100">×</button></div><div className="mt-5 grid gap-4 sm:grid-cols-2"><Mini label="Product category" value={selected.category} detail="Mock classification"/><Mini label="Compliance scheme" value={selected.scheme} detail="Verify against official BIS information"/></div><div className="mt-5 space-y-4 text-sm"><div><h3 className="font-bold text-slate-900">Summary</h3><p className="mt-1 leading-6 text-slate-500">{selected.summary}</p></div><div><h3 className="font-bold text-slate-900">Key requirements</h3><ul className="mt-1 list-disc space-y-1 pl-5 text-slate-500">{selected.requirements.map(item => <li key={item}>{item}</li>)}</ul></div><div><h3 className="font-bold text-slate-900">Documentation requirements</h3><p className="mt-1 text-slate-500">{selected.docs}</p></div><div><h3 className="font-bold text-slate-900">Testing requirements</h3><p className="mt-1 text-slate-500">{selected.testing}</p></div><div className="flex items-center gap-3"><h3 className="font-bold text-slate-900">Compliance status</h3><Badge tone={selected.status === "Applicable" ? "green" : selected.status === "Under Review" ? "amber" : "slate"}>{selected.status}</Badge></div></div><button onClick={() => setSelected(null)} className="mt-6 rounded-xl bg-blue-700 px-4 py-2.5 text-sm font-semibold text-white hover:bg-blue-800">Close details</button></div></div>}</Shell>;
}

export default function BisPortal({page}:{page:Page}){ return page === "dashboard" ? <Dashboard/> : page === "assistant" ? <Assistant/> : page === "passport" ? <Passport/> : page === "details" ? <Passport details/> : page === "standards" ? <StandardsDiscovery/> : page === "services" ? <Services/> : page === "alerts" ? <AlertsDiscovery/> : page === "reports" ? <Reports/> : <Settings/>; }
